from taf.collectors.tshark.collector import TsharkCollector
from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.core.templates.dynamic_class_creation import Creating
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TsharkCollectorFactory(NamedComponentFactory):
    """
           factory to create tshark collectors
    """

    def create(self, configuration, existing_arguments):
        """

        Create a tshark collector

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: TsharkCollector
        """
        resulting_arguments = {}
        self._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        return TsharkCollector(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(TsharkCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        for parameter_name in ["options", "tshark_path", "target_file_name", "start_timeout", "stop_timeout"]:
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]


class RemoteTsharkCollectorFactory(Creating("tool_executor", "SshExecutor", "executor"),
                                   Creating("file_getter", "SshFileGetter", "executor"),
                                   TsharkCollectorFactory):
    pass


class LocalTsharkCollectorFactory(Creating("tool_executor", "LocalExecutor"),
                                  Creating("file_getter", "LocalFileGetter"),
                                  TsharkCollectorFactory):
    pass


class TsharkCollectorFactorySelector(object):

    def create(self, configuration, existing_arguments):
        if "executor" in configuration:
            return RemoteTsharkCollectorFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        else:
            return LocalTsharkCollectorFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
